/**
 * PostgreSQL schema.
 *
 * Conventions
 * - Primary keys are UUIDs generated by the database (gen_random_uuid()).
 * - Money is BIGINT minor units (paise) with a CURRENCY code; never floats.
 * - Rates are INTEGER basis points (1 bps = 0.01%), bounded 0–10000.
 * - Timestamps are TIMESTAMPTZ (stored in UTC). Mutable tables carry
 *   updated_at, maintained by a trigger (see the migrations).
 * - Every foreign key states its ON DELETE rule and is indexed.
 * - Business invariants live in the database too (CHECKs, partial UNIQUE
 *   indexes), so a bug or a race in application code cannot corrupt data.
 */
import { sql } from "drizzle-orm";
import {
  bigint,
  boolean,
  char,
  check,
  index,
  integer,
  pgEnum,
  pgSequence,
  pgTable,
  primaryKey,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
  type AnyPgColumn,
} from "drizzle-orm/pg-core";
import {
  BILLING_INTERVALS,
  COMMISSION_KINDS,
  COMMISSION_STATUSES,
  LEAD_STATUSES,
  ORDER_KINDS,
  ORDER_STATUSES,
  PARTNER_STATUSES,
  PAYOUT_STATUSES,
  PRODUCT_STATUSES,
  PRODUCT_TYPES,
  QUOTE_STATUSES,
  ROLES,
  SUBSCRIPTION_STATUSES,
} from "@/domain/constants";

/* ------------------------------------------------------------------ enums */

export const roleEnum = pgEnum("user_role", ROLES);
export const productTypeEnum = pgEnum("product_type", PRODUCT_TYPES);
export const productStatusEnum = pgEnum("product_status", PRODUCT_STATUSES);
export const billingIntervalEnum = pgEnum("billing_interval", BILLING_INTERVALS);
export const partnerStatusEnum = pgEnum("partner_status", PARTNER_STATUSES);
export const orderKindEnum = pgEnum("order_kind", ORDER_KINDS);
export const orderStatusEnum = pgEnum("order_status", ORDER_STATUSES);
export const subscriptionStatusEnum = pgEnum("subscription_status", SUBSCRIPTION_STATUSES);
export const commissionKindEnum = pgEnum("commission_kind", COMMISSION_KINDS);
export const commissionStatusEnum = pgEnum("commission_status", COMMISSION_STATUSES);
export const payoutStatusEnum = pgEnum("payout_status", PAYOUT_STATUSES);
export const leadStatusEnum = pgEnum("lead_status", LEAD_STATUSES);
export const quoteStatusEnum = pgEnum("quote_status", QUOTE_STATUSES);

/** Human-friendly, gap-tolerant order numbers (C365-001001…), race-free. */
export const orderNumberSeq = pgSequence("order_number_seq", { startWith: 1001 });

/* ---------------------------------------------------------------- helpers */

const id = () => uuid("id").primaryKey().defaultRandom();
const tstz = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });
const createdAt = () => tstz("created_at").notNull().defaultNow();
const updatedAt = () => tstz("updated_at").notNull().defaultNow();
const money = (name: string) => bigint(name, { mode: "number" });
const currency = () => char("currency", { length: 3 }).notNull().default("INR");

/* ------------------------------------------------------------ identity */

export const users = pgTable(
  "users",
  {
    id: id(),
    email: text("email").notNull(),
    name: text("name").notNull(),
    passwordHash: text("password_hash").notNull(),
    role: roleEnum("role").notNull(),
    phone: text("phone"),
    companyName: text("company_name"),
    city: text("city"),
    /** First-touch partner attribution, fixed once set. */
    referredByPartnerId: uuid("referred_by_partner_id").references((): AnyPgColumn => users.id, { onDelete: "set null" }),
    lastLoginAt: tstz("last_login_at"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("users_email_key").on(t.email),
    check("users_email_lowercase", sql`${t.email} = lower(${t.email})`),
    check("users_not_self_referred", sql`${t.referredByPartnerId} is distinct from ${t.id}`),
    index("users_referred_by_idx").on(t.referredByPartnerId),
  ],
);

export const sessions = pgTable(
  "sessions",
  {
    /** SHA-256 of the session token; the raw token only ever lives in the cookie. */
    id: text("id").primaryKey(),
    userId: uuid("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
    expiresAt: tstz("expires_at").notNull(),
    createdAt: createdAt(),
  },
  (t) => [index("sessions_user_idx").on(t.userId), index("sessions_expires_idx").on(t.expiresAt)],
);

export const passwordResetTokens = pgTable(
  "password_reset_tokens",
  {
    id: text("id").primaryKey(), // SHA-256 of the emailed token
    userId: uuid("user_id").notNull().references(() => users.id, { onDelete: "cascade" }),
    expiresAt: tstz("expires_at").notNull(),
    usedAt: tstz("used_at"),
    createdAt: createdAt(),
  },
  (t) => [index("password_reset_tokens_user_idx").on(t.userId)],
);

export const partnerProfiles = pgTable(
  "partner_profiles",
  {
    userId: uuid("user_id").primaryKey().references(() => users.id, { onDelete: "cascade" }),
    code: text("code").notNull(),
    status: partnerStatusEnum("status").notNull().default("pending"),
    profession: text("profession").notNull(),
    region: text("region").notNull(),
    experience: text("experience"),
    payoutUpi: text("payout_upi"),
    agreementAcceptedAt: tstz("agreement_accepted_at").notNull(),
    approvedAt: tstz("approved_at"),
    reviewNote: text("review_note"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("partner_profiles_code_key").on(t.code),
    check("partner_profiles_code_format", sql`${t.code} ~ '^[A-Z0-9]{4,12}$'`),
    check("partner_profiles_approved_has_date", sql`${t.status} <> 'approved' or ${t.approvedAt} is not null`),
    index("partner_profiles_status_idx").on(t.status),
  ],
);

/* ------------------------------------------------------------- catalogue */

export const products = pgTable(
  "products",
  {
    id: id(),
    slug: text("slug").notNull(),
    name: text("name").notNull(),
    type: productTypeEnum("type").notNull(),
    category: text("category").notNull(),
    tagline: text("tagline").notNull(),
    description: text("description").notNull(),
    features: text("features").array().notNull().default(sql`'{}'::text[]`),
    /** Business types / apps this works with, e.g. "Retail", "Fitness". */
    worksWith: text("works_with").array().notNull().default(sql`'{}'::text[]`),
    status: productStatusEnum("status").notNull(),
    icon: text("icon").notNull(),
    trialDays: integer("trial_days"),
    /** Retail unit price for hardware; apps are priced through plans. */
    unitPrice: money("unit_price"),
    /** One-time partner margin on hardware sales, bps. */
    hardwareMargin: integer("hardware_margin"),
    sortOrder: integer("sort_order").notNull().default(0),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("products_slug_key").on(t.slug),
    check("products_slug_format", sql`${t.slug} ~ '^[a-z0-9]+(-[a-z0-9]+)*$'`),
    check("products_unit_price_positive", sql`${t.unitPrice} is null or ${t.unitPrice} > 0`),
    check("products_margin_range", sql`${t.hardwareMargin} is null or ${t.hardwareMargin} between 0 and 10000`),
    check("products_trial_days_range", sql`${t.trialDays} is null or ${t.trialDays} between 1 and 90`),
    index("products_listing_idx").on(t.type, t.status, t.sortOrder),
  ],
);

export const plans = pgTable(
  "plans",
  {
    id: id(),
    productId: uuid("product_id").notNull().references(() => products.id, { onDelete: "restrict" }),
    name: text("name").notNull(),
    interval: billingIntervalEnum("interval").notNull(),
    price: money("price").notNull(),
    currency: currency(),
    createdAt: createdAt(),
  },
  (t) => [
    unique("plans_product_interval_key").on(t.productId, t.interval),
    check("plans_price_positive", sql`${t.price} > 0`),
  ],
);

/** Volume pricing available to approved partners (bulk licences and hardware). */
export const partnerPriceTiers = pgTable(
  "partner_price_tiers",
  {
    productId: uuid("product_id").notNull().references(() => products.id, { onDelete: "cascade" }),
    minQuantity: integer("min_quantity").notNull(),
    unitPrice: money("unit_price").notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.productId, t.minQuantity] }),
    check("partner_price_tiers_min_quantity_positive", sql`${t.minQuantity} > 0`),
    check("partner_price_tiers_unit_price_positive", sql`${t.unitPrice} > 0`),
  ],
);

/* ---------------------------------------------------------------- orders */

export const orders = pgTable(
  "orders",
  {
    id: id(),
    number: text("number")
      .notNull()
      .default(sql`'C365-' || lpad(nextval('order_number_seq')::text, 6, '0')`),
    userId: uuid("user_id").notNull().references(() => users.id, { onDelete: "restrict" }),
    /** Partner credited for this order, if any. */
    partnerId: uuid("partner_id").references(() => users.id, { onDelete: "restrict" }),
    kind: orderKindEnum("kind").notNull(),
    status: orderStatusEnum("status").notNull().default("pending"),
    currency: currency(),
    subtotal: money("subtotal").notNull(),
    tax: money("tax").notNull(),
    total: money("total").notNull(),
    billingName: text("billing_name").notNull(),
    billingCompany: text("billing_company"),
    billingGstin: text("billing_gstin"),
    /** Subscription a renewal order extends. */
    subscriptionId: uuid("subscription_id").references((): AnyPgColumn => subscriptions.id, { onDelete: "restrict" }),
    paymentProvider: text("payment_provider"),
    /** Provider-side order / payment-link id, used to match webhooks and callbacks. */
    providerOrderId: text("provider_order_id"),
    /** Provider's payment id once paid (e.g. Razorpay pay_…). */
    paymentReference: text("payment_reference"),
    /** Hosted payment page for renewals billed by link. */
    paymentUrl: text("payment_url"),
    paidAt: tstz("paid_at"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("orders_number_key").on(t.number),
    uniqueIndex("orders_provider_order_key").on(t.paymentProvider, t.providerOrderId),
    // At most one unpaid renewal bill per subscription (the billing job relies on this).
    uniqueIndex("orders_one_open_renewal_key")
      .on(t.subscriptionId)
      .where(sql`${t.kind} = 'renewal' and ${t.status} = 'pending'`),
    check("orders_amounts_valid", sql`${t.subtotal} >= 0 and ${t.tax} >= 0 and ${t.total} = ${t.subtotal} + ${t.tax}`),
    check("orders_paid_consistency", sql`(${t.status} = 'paid') = (${t.paidAt} is not null)`),
    check("orders_renewal_has_subscription", sql`(${t.kind} = 'renewal') = (${t.subscriptionId} is not null)`),
    check("orders_gstin_format", sql`${t.billingGstin} is null or ${t.billingGstin} ~ '^[0-9]{2}[A-Z0-9]{13}$'`),
    index("orders_user_created_idx").on(t.userId, t.createdAt.desc()),
    index("orders_partner_idx").on(t.partnerId),
    index("orders_subscription_idx").on(t.subscriptionId),
    index("orders_status_created_idx").on(t.status, t.createdAt),
  ],
);

export const orderItems = pgTable(
  "order_items",
  {
    id: id(),
    orderId: uuid("order_id").notNull().references(() => orders.id, { onDelete: "cascade" }),
    productId: uuid("product_id").notNull().references(() => products.id, { onDelete: "restrict" }),
    planId: uuid("plan_id").references(() => plans.id, { onDelete: "restrict" }),
    /** Snapshot of what was sold, so later catalogue edits never rewrite history. */
    description: text("description").notNull(),
    quantity: integer("quantity").notNull(),
    unitPrice: money("unit_price").notNull(),
    lineTotal: money("line_total").notNull(),
  },
  (t) => [
    check("order_items_quantity_positive", sql`${t.quantity} > 0`),
    check("order_items_line_total", sql`${t.unitPrice} >= 0 and ${t.lineTotal} = ${t.unitPrice} * ${t.quantity}`),
    index("order_items_order_idx").on(t.orderId),
    index("order_items_product_idx").on(t.productId),
  ],
);

/* --------------------------------------------------------- subscriptions */

export const subscriptions = pgTable(
  "subscriptions",
  {
    id: id(),
    userId: uuid("user_id").notNull().references(() => users.id, { onDelete: "restrict" }),
    productId: uuid("product_id").notNull().references(() => products.id, { onDelete: "restrict" }),
    planId: uuid("plan_id").references(() => plans.id, { onDelete: "restrict" }),
    partnerId: uuid("partner_id").references(() => users.id, { onDelete: "restrict" }),
    status: subscriptionStatusEnum("status").notNull(),
    licenseKey: text("license_key").notNull(),
    currentPeriodStart: tstz("current_period_start").notNull(),
    currentPeriodEnd: tstz("current_period_end").notNull(),
    cancelAtPeriodEnd: boolean("cancel_at_period_end").notNull().default(false),
    renewalCount: integer("renewal_count").notNull().default(0),
    /** Set when activated from a partner's bulk licence key rather than paid directly. */
    fromLicenceKeyId: uuid("from_licence_key_id").references((): AnyPgColumn => licenceKeys.id, { onDelete: "restrict" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    // One subscription record per business per app; its history lives in orders.
    unique("subscriptions_user_product_key").on(t.userId, t.productId),
    uniqueIndex("subscriptions_license_key_key").on(t.licenseKey),
    check("subscriptions_period_order", sql`${t.currentPeriodEnd} > ${t.currentPeriodStart}`),
    check("subscriptions_renewal_count_nonnegative", sql`${t.renewalCount} >= 0`),
    check("subscriptions_paid_has_plan", sql`${t.status} = 'trialing' or ${t.planId} is not null or ${t.status} = 'expired'`),
    index("subscriptions_partner_status_idx").on(t.partnerId, t.status),
    index("subscriptions_due_idx").on(t.status, t.currentPeriodEnd),
  ],
);

/** Licence keys issued from a partner's bulk licence order, redeemable by clients. */
export const licenceKeys = pgTable(
  "licence_keys",
  {
    id: id(),
    key: text("key").notNull(),
    orderItemId: uuid("order_item_id").notNull().references(() => orderItems.id, { onDelete: "restrict" }),
    partnerId: uuid("partner_id").notNull().references(() => users.id, { onDelete: "restrict" }),
    productId: uuid("product_id").notNull().references(() => products.id, { onDelete: "restrict" }),
    redeemedAt: tstz("redeemed_at"),
    redeemedByUserId: uuid("redeemed_by_user_id").references(() => users.id, { onDelete: "restrict" }),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("licence_keys_key_key").on(t.key),
    check("licence_keys_redemption_consistent", sql`(${t.redeemedAt} is null) = (${t.redeemedByUserId} is null)`),
    index("licence_keys_partner_idx").on(t.partnerId),
    index("licence_keys_order_item_idx").on(t.orderItemId),
  ],
);

/* ---------------------------------------------------- partner earnings */

export const payouts = pgTable(
  "payouts",
  {
    id: id(),
    partnerId: uuid("partner_id").notNull().references(() => users.id, { onDelete: "restrict" }),
    period: char("period", { length: 7 }).notNull(), // YYYY-MM
    amount: money("amount").notNull(),
    currency: currency(),
    status: payoutStatusEnum("status").notNull().default("pending"),
    reference: text("reference"),
    paidAt: tstz("paid_at"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    check("payouts_period_format", sql`${t.period} ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'`),
    check("payouts_amount_positive", sql`${t.amount} > 0`),
    check("payouts_paid_consistency", sql`(${t.status} = 'paid') = (${t.paidAt} is not null and ${t.reference} is not null)`),
    index("payouts_partner_idx").on(t.partnerId, t.createdAt.desc()),
  ],
);

export const commissions = pgTable(
  "commissions",
  {
    id: id(),
    partnerId: uuid("partner_id").notNull().references(() => users.id, { onDelete: "restrict" }),
    orderId: uuid("order_id").notNull().references(() => orders.id, { onDelete: "restrict" }),
    orderItemId: uuid("order_item_id").notNull().references(() => orderItems.id, { onDelete: "restrict" }),
    subscriptionId: uuid("subscription_id").references(() => subscriptions.id, { onDelete: "restrict" }),
    kind: commissionKindEnum("kind").notNull(),
    description: text("description").notNull(),
    baseAmount: money("base_amount").notNull(),
    /** Rate and tier at the time of sale, kept so tier changes never rewrite history. */
    rate: integer("rate").notNull(),
    tier: text("tier").notNull(),
    amount: money("amount").notNull(),
    currency: currency(),
    status: commissionStatusEnum("status").notNull().default("pending"),
    payoutId: uuid("payout_id").references(() => payouts.id, { onDelete: "restrict" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    // Idempotency: an order line earns each kind of commission at most once.
    unique("commissions_order_item_kind_key").on(t.orderItemId, t.kind),
    check("commissions_amounts_nonnegative", sql`${t.baseAmount} >= 0 and ${t.amount} >= 0`),
    check("commissions_rate_range", sql`${t.rate} between 0 and 10000`),
    check("commissions_tier_valid", sql`${t.tier} in ('channel', 'silver', 'gold', 'platinum')`),
    check("commissions_payout_consistency", sql`(${t.status} in ('in_payout', 'paid')) = (${t.payoutId} is not null)`),
    index("commissions_partner_status_idx").on(t.partnerId, t.status, t.createdAt),
    index("commissions_payout_idx").on(t.payoutId),
    index("commissions_order_idx").on(t.orderId),
  ],
);

/* ------------------------------------------------------------ pipeline */

export const leads = pgTable(
  "leads",
  {
    id: id(),
    partnerId: uuid("partner_id").notNull().references(() => users.id, { onDelete: "cascade" }),
    businessName: text("business_name").notNull(),
    contactName: text("contact_name").notNull(),
    email: text("email"),
    phone: text("phone"),
    productId: uuid("product_id").references(() => products.id, { onDelete: "set null" }),
    status: leadStatusEnum("status").notNull().default("new"),
    notes: text("notes"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    check("leads_has_contact", sql`${t.email} is not null or ${t.phone} is not null`),
    index("leads_partner_updated_idx").on(t.partnerId, t.updatedAt.desc()),
  ],
);

export const quoteRequests = pgTable(
  "quote_requests",
  {
    id: id(),
    productId: uuid("product_id").notNull().references(() => products.id, { onDelete: "restrict" }),
    userId: uuid("user_id").references(() => users.id, { onDelete: "set null" }),
    partnerId: uuid("partner_id").references(() => users.id, { onDelete: "set null" }),
    name: text("name").notNull(),
    email: text("email").notNull(),
    phone: text("phone").notNull(),
    city: text("city").notNull(),
    message: text("message"),
    status: quoteStatusEnum("status").notNull().default("open"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("quote_requests_status_created_idx").on(t.status, t.createdAt.desc())],
);

/** Append-only record of sensitive actions, for accountability. */
export const auditEvents = pgTable(
  "audit_events",
  {
    id: id(),
    actorId: uuid("actor_id").references(() => users.id, { onDelete: "set null" }),
    action: text("action").notNull(),
    entityId: text("entity_id"),
    detail: text("detail"),
    createdAt: createdAt(),
  },
  (t) => [index("audit_events_created_idx").on(t.createdAt.desc()), index("audit_events_actor_idx").on(t.actorId)],
);

export type User = typeof users.$inferSelect;
export type PartnerProfile = typeof partnerProfiles.$inferSelect;
export type Product = typeof products.$inferSelect;
export type Plan = typeof plans.$inferSelect;
export type Order = typeof orders.$inferSelect;
export type OrderItem = typeof orderItems.$inferSelect;
export type Subscription = typeof subscriptions.$inferSelect;
export type Commission = typeof commissions.$inferSelect;
export type Payout = typeof payouts.$inferSelect;
export type Lead = typeof leads.$inferSelect;
export type QuoteRequest = typeof quoteRequests.$inferSelect;
